var n=`0405-cullen-skink`;var t=`world-0405`;var o=`GB`;var a=`northern-europe`;var s=4;var d=44;var r={en:`Cullen Skink`,ua:`Каллен скінк`};var l={en:`A traditional dish from United Kingdom, centered on yellow onion, potato, whole cow milk, haddock. A measured home-kitchen version organized by cooking step. Uses fresh haddock and a little smoked paprika in place of traditional smoked haddock.`,ua:`Традиційна страва кухні країни Велика Британія. Основні складники: жовта цибуля, картопля, цільне коров'яче молоко, пікша. Домашній варіант із кількостями продуктів за етапами приготування. Замість традиційної копченої пікші використано свіжу пікшу та трохи копченої паприки.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,180,`g`],[`unsalted-butter`,50,`g`]]},{en:`Cook the listed ingredients in simmering water for about 20 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 20 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:20,i:[[`potato`,400,`g`],[`whole-cow-milk`,400,`ml`],[`water`,250,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 12 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 12 хвилин до готовності й м’якості.`,t:[`poaching`],m:12,i:[[`haddock`,400,`g`],[`smoked-paprika`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,15,`g`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:n,id:t,country:`GB`,region:a,servings:4,minutes:44,title:r,text:l,steps:u};export{o as country,g as default,t as id,d as minutes,a as region,s as servings,n as slug,u as steps,l as text,r as title};